import Foundation

/// FSRS-6 scheduler, ported from the reference implementation
/// (open-spaced-repetition/py-fsrs v6.3.1). The unit tests validate this port
/// against golden vectors generated by that package.
///
/// Model summary:
///  - Each card carries (stability S, difficulty D).
///  - Retrievability R(t) = (1 + FACTOR * t / S)^DECAY, a power forgetting curve
///    where DECAY = -w20 is itself a learned parameter in FSRS-6.
///  - The next interval solves R(t) = desiredRetention for t.
public struct FSRS: Sendable {

    /// FSRS-6 default parameters (21 weights) from py-fsrs 6.3.1.
    public static let defaultParameters: [Double] = [
        0.212, 1.2931, 2.3065, 8.2956, 6.4133, 0.8334, 3.0194, 0.001,
        1.8722, 0.1666, 0.796, 1.4835, 0.0614, 0.2629, 1.6483, 0.6014,
        1.8729, 0.5425, 0.0912, 0.0658, 0.1542,
    ]

    public static let minDifficulty = 1.0
    public static let maxDifficulty = 10.0
    public static let minStability = 0.001

    public var parameters: [Double]
    public var desiredRetention: Double
    /// Intra-day steps for cards in the learning phase.
    public var learningSteps: [TimeInterval]
    /// Intra-day steps after a lapse (relearning phase).
    public var relearningSteps: [TimeInterval]
    /// Upper bound on scheduled interval, in days.
    public var maximumIntervalDays: Int
    public var enableFuzzing: Bool

    private var decay: Double { -parameters[20] }
    private var factor: Double { pow(0.9, 1.0 / decay) - 1.0 }

    public init(
        parameters: [Double] = FSRS.defaultParameters,
        desiredRetention: Double = 0.9,
        learningSteps: [TimeInterval] = [60, 600],
        relearningSteps: [TimeInterval] = [600],
        maximumIntervalDays: Int = 36500,
        enableFuzzing: Bool = true
    ) {
        precondition(parameters.count == 21, "FSRS-6 requires 21 parameters")
        self.parameters = parameters
        self.desiredRetention = desiredRetention
        self.learningSteps = learningSteps
        self.relearningSteps = relearningSteps
        self.maximumIntervalDays = maximumIntervalDays
        self.enableFuzzing = enableFuzzing
    }

    // MARK: - Public API

    /// Predicted probability of recalling `card` at `date`.
    public func retrievability(of card: Card, at date: Date) -> Double {
        guard let memory = card.memory, let lastReview = card.lastReview else { return 0 }
        let elapsedDays = max(0, wholeDays(from: lastReview, to: date))
        return pow(1 + factor * Double(elapsedDays) / memory.stability, decay)
    }

    /// Review `card` with `rating` at `date`; returns the updated card and a log entry.
    /// Pass a seeded generator for deterministic fuzzing.
    public func review<G: RandomNumberGenerator>(
        card: Card,
        rating: Rating,
        at date: Date,
        inGateSession: Bool = false,
        using generator: inout G
    ) -> (card: Card, log: ReviewLog) {
        var card = card
        let phaseBefore = card.phase
        let daysSinceLastReview = card.lastReview.map { wholeDays(from: $0, to: date) }

        // A brand-new card enters the learning phase at step 0, matching the
        // reference implementation where fresh cards are State.Learning.
        if card.phase == .new {
            card.phase = .learning
            card.stepIndex = 0
        }

        let nextInterval: TimeInterval
        switch card.phase {
        case .new:
            fatalError("unreachable")

        case .learning:
            updateMemory(&card, rating: rating, at: date, daysSinceLastReview: daysSinceLastReview)
            nextInterval = stepInterval(
                &card, rating: rating, steps: learningSteps
            )

        case .review:
            let memory = card.memory!
            if let days = daysSinceLastReview, days < 1 {
                card.memory?.stability = shortTermStability(stability: memory.stability, rating: rating)
            } else {
                card.memory?.stability = nextStability(
                    difficulty: memory.difficulty,
                    stability: memory.stability,
                    retrievability: retrievability(of: card, at: date),
                    rating: rating
                )
            }
            card.memory?.difficulty = nextDifficulty(difficulty: memory.difficulty, rating: rating)

            if rating == .again {
                card.lapses += 1
                if relearningSteps.isEmpty {
                    nextInterval = daysToSeconds(nextIntervalDays(stability: card.memory!.stability))
                } else {
                    card.phase = .relearning
                    card.stepIndex = 0
                    nextInterval = relearningSteps[0]
                }
            } else {
                nextInterval = daysToSeconds(nextIntervalDays(stability: card.memory!.stability))
            }

        case .relearning:
            updateMemory(&card, rating: rating, at: date, daysSinceLastReview: daysSinceLastReview)
            nextInterval = stepInterval(
                &card, rating: rating, steps: relearningSteps
            )
        }

        var interval = nextInterval
        if enableFuzzing, card.phase == .review {
            interval = fuzzedInterval(interval, using: &generator)
        }

        card.due = date.addingTimeInterval(interval)
        card.lastReview = date
        card.reps += 1

        let log = ReviewLog(
            cardID: card.id,
            reviewedAt: date,
            rating: rating,
            phaseBefore: phaseBefore,
            scheduledDays: interval / 86_400,
            inGateSession: inGateSession
        )
        return (card, log)
    }

    /// Convenience overload using the system RNG.
    public func review(
        card: Card, rating: Rating, at date: Date, inGateSession: Bool = false
    ) -> (card: Card, log: ReviewLog) {
        var generator = SystemRandomNumberGenerator()
        return review(card: card, rating: rating, at: date, inGateSession: inGateSession, using: &generator)
    }

    // MARK: - Learning/relearning step machinery

    /// Updates (S, D) for a card in the learning or relearning phase.
    private func updateMemory(
        _ card: inout Card, rating: Rating, at date: Date, daysSinceLastReview: Int?
    ) {
        if card.memory == nil {
            card.memory = MemoryState(
                stability: initialStability(rating: rating),
                difficulty: initialDifficulty(rating: rating, clamp: true)
            )
        } else if let days = daysSinceLastReview, days < 1 {
            card.memory!.stability = shortTermStability(stability: card.memory!.stability, rating: rating)
            card.memory!.difficulty = nextDifficulty(difficulty: card.memory!.difficulty, rating: rating)
        } else {
            card.memory!.stability = nextStability(
                difficulty: card.memory!.difficulty,
                stability: card.memory!.stability,
                retrievability: retrievability(of: card, at: date),
                rating: rating
            )
            card.memory!.difficulty = nextDifficulty(difficulty: card.memory!.difficulty, rating: rating)
        }
    }

    /// Advances the step index per the rating and returns the next interval in
    /// seconds; graduates the card to `.review` when steps are exhausted.
    private func stepInterval(
        _ card: inout Card, rating: Rating, steps: [TimeInterval]
    ) -> TimeInterval {
        func graduate() -> TimeInterval {
            card.phase = .review
            card.stepIndex = 0
            return daysToSeconds(nextIntervalDays(stability: card.memory!.stability))
        }

        if steps.isEmpty || (card.stepIndex >= steps.count && rating != .again) {
            return graduate()
        }
        switch rating {
        case .again:
            card.stepIndex = 0
            return steps[0]
        case .hard:
            // Step index stays put; a Hard on the first step lands between it
            // and the next step (or 1.5x if it is the only step).
            if card.stepIndex == 0 && steps.count == 1 {
                return steps[0] * 1.5
            } else if card.stepIndex == 0 && steps.count >= 2 {
                return (steps[0] + steps[1]) / 2.0
            }
            return steps[card.stepIndex]
        case .good:
            if card.stepIndex + 1 == steps.count {
                return graduate()
            }
            card.stepIndex += 1
            return steps[card.stepIndex]
        case .easy:
            return graduate()
        }
    }

    // MARK: - FSRS-6 formulas

    func initialStability(rating: Rating) -> Double {
        max(parameters[rating.rawValue - 1], FSRS.minStability)
    }

    func initialDifficulty(rating: Rating, clamp: Bool) -> Double {
        let d = parameters[4] - exp(parameters[5] * Double(rating.rawValue - 1)) + 1
        return clamp ? clampDifficulty(d) : d
    }

    /// Interval (whole days, >= 1) at which retrievability decays to `desiredRetention`.
    func nextIntervalDays(stability: Double) -> Int {
        let raw = (stability / factor) * (pow(desiredRetention, 1.0 / decay) - 1)
        // .toNearestOrEven matches Python's round(), which the reference uses.
        return min(max(Int(raw.rounded(.toNearestOrEven)), 1), maximumIntervalDays)
    }

    /// Same-day review stability update (FSRS-6 short-term memory component).
    func shortTermStability(stability: Double, rating: Rating) -> Double {
        var increase = exp(parameters[17] * (Double(rating.rawValue) - 3 + parameters[18]))
            * pow(stability, -parameters[19])
        if rating == .good || rating == .easy {
            increase = max(increase, 1.0)
        }
        return max(stability * increase, FSRS.minStability)
    }

    func nextDifficulty(difficulty: Double, rating: Rating) -> Double {
        let deltaD = -(parameters[6] * Double(rating.rawValue - 3))
        let damped = difficulty + (10.0 - difficulty) * deltaD / 9.0
        let target = initialDifficulty(rating: .easy, clamp: false)
        let meanReverted = parameters[7] * target + (1 - parameters[7]) * damped
        return clampDifficulty(meanReverted)
    }

    func nextStability(
        difficulty: Double, stability: Double, retrievability: Double, rating: Rating
    ) -> Double {
        let next: Double
        if rating == .again {
            next = nextForgetStability(
                difficulty: difficulty, stability: stability, retrievability: retrievability)
        } else {
            next = nextRecallStability(
                difficulty: difficulty, stability: stability,
                retrievability: retrievability, rating: rating)
        }
        return max(next, FSRS.minStability)
    }

    func nextForgetStability(
        difficulty: Double, stability: Double, retrievability: Double
    ) -> Double {
        let longTerm = parameters[11]
            * pow(difficulty, -parameters[12])
            * (pow(stability + 1, parameters[13]) - 1)
            * exp((1 - retrievability) * parameters[14])
        let shortTerm = stability / exp(parameters[17] * parameters[18])
        return min(longTerm, shortTerm)
    }

    func nextRecallStability(
        difficulty: Double, stability: Double, retrievability: Double, rating: Rating
    ) -> Double {
        let hardPenalty = rating == .hard ? parameters[15] : 1
        let easyBonus = rating == .easy ? parameters[16] : 1
        return stability * (
            1 + exp(parameters[8])
                * (11 - difficulty)
                * pow(stability, -parameters[9])
                * (exp((1 - retrievability) * parameters[10]) - 1)
                * hardPenalty
                * easyBonus
        )
    }

    // MARK: - Fuzzing

    private static let fuzzRanges: [(start: Double, end: Double, factor: Double)] = [
        (2.5, 7.0, 0.15), (7.0, 20.0, 0.1), (20.0, .infinity, 0.05),
    ]

    func fuzzedInterval<G: RandomNumberGenerator>(
        _ interval: TimeInterval, using generator: inout G
    ) -> TimeInterval {
        let intervalDays = Int(interval / 86_400)
        guard Double(intervalDays) >= 2.5 else { return interval }

        var delta = 1.0
        for range in FSRS.fuzzRanges {
            delta += range.factor * max(min(Double(intervalDays), range.end) - range.start, 0)
        }
        var minIvl = max(2, Int((Double(intervalDays) - delta).rounded()))
        let maxIvl = min(Int((Double(intervalDays) + delta).rounded()), maximumIntervalDays)
        minIvl = min(minIvl, maxIvl)

        let roll = Double.random(in: 0..<1, using: &generator)
        let fuzzed = min(Int((roll * Double(maxIvl - minIvl + 1) + Double(minIvl)).rounded()), maximumIntervalDays)
        return daysToSeconds(fuzzed)
    }

    // MARK: - Helpers

    private func clampDifficulty(_ d: Double) -> Double {
        min(max(d, FSRS.minDifficulty), FSRS.maxDifficulty)
    }

    private func daysToSeconds(_ days: Int) -> TimeInterval {
        Double(days) * 86_400
    }

    /// Truncated whole days between two dates, matching Python's
    /// `(a - b).days` semantics (floor division of seconds).
    private func wholeDays(from start: Date, to end: Date) -> Int {
        Int(floor(end.timeIntervalSince(start) / 86_400))
    }
}
